  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-01-01', 'New year, new system. Not resolutions — habits. Starting with 10 and tracking every single one. The cold shower nearly broke me on day 1. Nearly.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-01-07', 'First full week done. 82% completion. Gym was the hardest — skipped Friday because I told myself I would go Saturday. Did not. Fixing the excuse next week.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-01-14', 'Two weeks in. Cold shower is now automatic. The moment of hesitation before turning the handle is getting shorter. That is the whole game.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-01-21', 'Meditation streak hit 14 days. I do not feel enlightened. I feel slightly less reactive, which is probably the same thing at this stage.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-01-31', 'January closed at 79% overall. Cold shower 96%. No sugar 68% — weekends are the leak. GYM 91% on applicable days. February is about patching the gaps.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-02-03', 'Changed strategy on sugar. Instead of willpower, I stopped buying it. Cannot fail at not eating what is not in the house.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-02-10', 'Reading habit is the most underrated one. 10 pages a day is 300 pages a month, 3600 a year. Compounding applies to knowledge too.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-02-14', 'Missed 3 days of planning this week. The days I do not plan are the days I feel like I am reacting to life instead of directing it.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-02-28', 'February: 81% overall. No sugar improved to 74%. Cold shower still near-perfect. Most improved: planning. Most to fix: sleep consistency.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-03-07', 'Week 1 of March. Building a project while maintaining the habits is a test. Coding streak and habit streak running simultaneously.') ON CONFLICT DO NOTHING;
  INSERT INTO public.journal_notes (user_id, note_date, content) VALUES (uid, '2026-03-14', 'The heatmap is starting to look like something. Two months of consistent green squares makes you want to protect the streak. The visual accountability is real.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_cold, 2026, 0, 'January was about tolerating it. By week 3 it stopped feeling like punishment and started feeling like a decision. That distinction matters.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_gym, 2026, 0, 'Skipped 2 Fridays. The pattern is always the same: told myself I would go Saturday instead. Blocking gym as non-negotiable on calendar next month.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_nosugar, 2026, 0, 'Weekends are the weak point. Social situations and tiredness are the two triggers. Awareness is step one.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_cold, 2026, 1, 'No longer dreading it. That is the milestone. February is when it became a habit rather than a challenge.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_read, 2026, 1, 'Finished two books this month. 10 pages minimum per day. Some days it was 40. The minimum creates the floor; curiosity creates the ceiling.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_sleep, 2026, 1, 'Still the hardest one to close. Strategy for March: phone charges outside the bedroom. Remove the friction source entirely.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_code, 2026, 2, 'Building the habit tracker in the coding sessions. The 1-hour minimum is a floor — most sessions ran 2-3 hours once started.') ON CONFLICT DO NOTHING;
  INSERT INTO public.habit_notes (user_id, habit_id, year, month, content) VALUES (uid, h_planning, 2026, 2, 'Evening planning wins. You close the day with intention instead of opening tomorrow in reactive mode.') ON CONFLICT DO NOTHING;
  INSERT INTO public.user_settings (user_id, dark_mode, reminder_on, reminder_time)
