-- ============================================================
--  HABIT TRACKER — Dummy Data
--
--  HOW TO USE:
--  1. Sign up in the app and note your email
--  2. Go to: Supabase Dashboard → Authentication → Users
--  3. Copy your user UUID (e.g. 8d8862b0-7ca7-48c3-a6fe-...)
--  4. In this file: Find & Replace  <<YOUR_USER_ID>>
--     with your actual UUID (keep the single quotes around it)
--  5. Paste the entire file into Supabase SQL Editor → Run
--
--  Inserts: 10 habits, ~594 checks (Jan–Mar 2026),
--           75 mood logs, 11 journal entries, 8 habit notes
-- ============================================================

DO $$
DECLARE
  uid uuid := '<<YOUR_USER_ID>>';

  cat_health uuid; cat_mind uuid; cat_work uuid; cat_body uuid;
  h_wake uuid; h_cold uuid; h_gym uuid; h_meditate uuid; h_read uuid;
  h_nosugar uuid; h_planning uuid; h_code uuid; h_walk uuid; h_sleep uuid;

BEGIN

-- ── Guard: make sure the user exists ──────────────────────
IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = uid) THEN
  RAISE EXCEPTION 'User % not found. Replace <<YOUR_USER_ID>> with your real UUID.', uid;
END IF;

-- ── Generate UUIDs ────────────────────────────────────────
cat_health := gen_random_uuid(); cat_mind  := gen_random_uuid();
cat_work   := gen_random_uuid(); cat_body  := gen_random_uuid();

h_wake     := gen_random_uuid(); h_cold     := gen_random_uuid();
h_gym      := gen_random_uuid(); h_meditate := gen_random_uuid();
h_read     := gen_random_uuid(); h_nosugar  := gen_random_uuid();
h_planning := gen_random_uuid(); h_code     := gen_random_uuid();
h_walk     := gen_random_uuid(); h_sleep    := gen_random_uuid();

-- ── CATEGORIES ────────────────────────────────────────────

-- ── HABITS ────────────────────────────────────────────────

-- ── HABIT CHECKS ──────────────────────────────────────────

-- ── MOOD LOGS ──────────────────────────────────────────────

-- ── JOURNAL NOTES ──────────────────────────────────────────

-- ── HABIT NOTES ────────────────────────────────────────────

-- ── USER SETTINGS ────────────────────────────────────────
  VALUES (uid, false, false, '06:30')
  ON CONFLICT (user_id) DO UPDATE
    SET reminder_time = '06:30';

END $$;
